// Validate and enrich new hire data
const input = $input.first().json;

// Validate required fields
const required = ['employee_id', 'first_name', 'last_name', 'email', 'department', 'manager_email', 'start_date'];
const missing = required.filter(field => !input[field]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

// Calculate days until start
const startDate = new Date(input.start_date);
const today = new Date();
const daysUntilStart = Math.ceil((startDate - today) / (1000 * 60 * 60 * 24));

// Generate welcome message
const welcomeMessages = [
  `We're thrilled to have ${input.first_name} joining the ${input.department} team! 🎉`,
  `Please join us in welcoming ${input.first_name} ${input.last_name} to INTINC! 🌟`,
  `Exciting news! ${input.first_name} is joining us as part of ${input.department}! 🚀`
];
const randomWelcome = welcomeMessages[Math.floor(Math.random() * welcomeMessages.length)];

return {
  ...input,
  full_name: `${input.first_name} ${input.last_name}`,
  days_until_start: daysUntilStart,
  welcome_message: randomWelcome,
  onboarding_id: `ONB-${Date.now()}`,
  created_at: new Date().toISOString(),
  status: 'pending'
};

